def transform(grid):
    # Compact the repeated patterned board. Each large tile contributes its
    # interior color; sparse colored marks on divider rows replace positions.
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    tile = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    # Output cells align with the array of repeated tile interiors.
    row_starts = list(range(1, h, 7))
    col_starts = list(range(1, w, 5))
    out = [[grid[r][c] for c in col_starts] for r in row_starts]
    # Markers on horizontal separators encode non-default output cells;
    # project each marker to nearest tile location on its lower/right side.
    for r in range(h):
        if r % 7 == 0:
            ri = min(r // 7, len(out)-1)
            for c, v in enumerate(grid[r]):
                if v not in (bg, tile):
                    ci = max(0, min((c-15)//5 + 2, len(out[ri])-1))
                    out[ri][ci] = v
    return out

